import 'dart:io';
import 'dart:typed_data';

/// Real PNG bytes generated by the server's own identicon algorithm
/// (`server/src/bb_server/avatars.py`) for synthetic accounts, plus one
/// uploaded-style replacement image.
///
/// Regeneration command (from the repository root):
///
/// ```bash
/// uv run --project server --locked python - <<'PY'
/// from pathlib import Path
/// from PIL import Image
/// from bb_server.avatars import identicon
/// out = Path('client/test/fixtures/avatars')
/// for account in ('10000001', '10000002'):
///     (out / f'{account}.png').write_bytes(identicon(account))
/// Image.new('RGBA', (250, 250), (32, 96, 210, 255)).save(out / 'peer-replaced.png')
/// PY
/// ```
Uint8List avatarFixture(String name) =>
    File('test/fixtures/avatars/$name').readAsBytesSync();

Uint8List get selfIdenticon => avatarFixture('10000001.png');

Uint8List get peerIdenticon => avatarFixture('10000002.png');

Uint8List get peerReplacedAvatar => avatarFixture('peer-replaced.png');
